161	  /// 与固件 `sanitize_pkg` 一致；超长截断，防止异常包名撑爆路径。
162	  static String sanitizePackage(String pkg, [int maxChars = packageMax]) {
163	    final out = StringBuffer();
164	    for (final r in pkg.runes) {
165	      if (out.length >= maxChars) break;
166	      final c = String.fromCharCode(r);
167	      if (RegExp(r'[A-Za-z0-9._-]').hasMatch(c)) {
168	        out.write(c);
169	      } else {
170	        out.write('_');
171	      }
172	    }
173	    return out.toString();
174	  }
175	
176	  /// 线上文件名：包名清洗后加 `.png`，总长不超过 [iconNameMax]。
177	  static String iconFileName(String packageName) {
178	    const ext = '.png';
179	    final maxStem = iconNameMax - ext.length;
180	    final cap = maxStem < packageMax ? maxStem : packageMax;
181	    final stem = sanitizePackage(packageName, cap);
182	    if (stem.isEmpty) return '';
183	    return '$stem$ext';
184	  }
185	
186	  /// 去掉路径、清洗非法字符。`.` / `..` / 空串视为无效。
187	  static String wireName(String raw) {
188	    var s = raw.trim().replaceAll('\\', '/');
189	    if (s.isEmpty) return '';
190	    final slash = s.lastIndexOf('/');
191	    if (slash >= 0) s = s.substring(slash + 1);
192	    s = sanitizePackage(s, iconNameMax);
193	    if (s.isEmpty || s == '.' || s == '..') return '';
194	    return s;
195	  }
