197	  /// 设备侧 FS 相对路径（App 上传时应答 `FS_NEED` 时使用，不进 0xFF17）。
198	  static String iconFsPath(String fileName) {
199	    final name = wireName(fileName);
200	    if (name.isEmpty) return '';
201	    return '$iconDir/$name';
202	  }
