321	  /// 转成线上相对路径：根目录为空，去掉误传的 `/mnt/lfs` 前缀。
322	  static String wirePath(String path) {
323	    var value = path.trim();
324	    if (value.startsWith(storageRoot)) {
325	      value = value.substring(storageRoot.length);
326	    }
327	    while (value.startsWith('/')) {
328	      value = value.substring(1);
329	    }
330	    if (value == '.') {
331	      return '';
332	    }
333	    return value;
334	  }
