343	  /// 上一级相对路径。
344	  static String parentRel(String dir) {
345	    final base = wirePath(dir);
346	    if (base.isEmpty) return '';
347	    final i = base.lastIndexOf('/');
348	    if (i <= 0) return '';
349	    return base.substring(0, i);
