380	/// 一帧 `0xFF16` FS Data。
381	class CompanionFsFrame {
382	  /// 解析 8 字节头 + payload。
383	  CompanionFsFrame({
384	    required this.cmd,
385	    required this.tid,
386	    required this.flags,
387	    required this.status,
388	    required this.seq,
389	    required this.payload,
390	  });
391	
392	  final int cmd;
393	  final int tid;
394	  final int flags;
395	  final int status;
396	  final int seq;
397	  final Uint8List payload;
398	
399	  bool get isLast => flags & CompanionFs.flagLast != 0;
400	  bool get isErr => flags & CompanionFs.flagErr != 0;
401	
402	  factory CompanionFsFrame.fromBytes(List<int> data) {
403	    if (data.length < CompanionFs.dataHdrLen) {
404	      throw FormatException('FS 帧短于 8 字节: ${data.length}');
405	    }
406	    final bd = ByteData.sublistView(Uint8List.fromList(data));
407	    final len = bd.getUint16(6, Endian.little);
408	    final end = CompanionFs.dataHdrLen + len;
409	    if (data.length < end) {
410	      throw FormatException('FS 帧 payload 截断: 声明 $len，实际 ${data.length - 8}');
411	    }
412	    return CompanionFsFrame(
413	      cmd: bd.getUint8(0),
414	      tid: bd.getUint8(1),
415	      flags: bd.getUint8(2),
416	      status: bd.getUint8(3),
417	      seq: bd.getUint16(4, Endian.little),
418	      payload: Uint8List.fromList(data.sublist(CompanionFs.dataHdrLen, end)),
419	    );
420	  }
421	}
