423	/// LIST / STAT 条目。
424	class CompanionFsEntry {
425	  const CompanionFsEntry({
426	    required this.type,
427	    required this.size,
428	    required this.mtime,
429	    required this.name,
430	  });
431	
432	  final int type;
433	  final int size;
434	  final int mtime;
435	  final String name;
436	
437	  bool get isDir => type == CompanionFs.entryDir;
438	
439	  static List<CompanionFsEntry> parseList(Uint8List payload) {
440	    final out = <CompanionFsEntry>[];
441	    var i = 0;
442	    final bd = ByteData.sublistView(payload);
443	    while (i + 10 <= payload.length) {
444	      final type = payload[i];
445	      final size = bd.getUint32(i + 1, Endian.little);
446	      final mtime = bd.getUint32(i + 5, Endian.little);
447	      final nlen = payload[i + 9];
448	      i += 10;
449	      if (i + nlen > payload.length) break;
450	      final name = utf8.decode(
451	        payload.sublist(i, i + nlen),
452	        allowMalformed: true,
453	      );
454	      i += nlen;
455	      out.add(CompanionFsEntry(type: type, size: size, mtime: mtime, name: name));
456	    }
457	    return out;
458	  }
459	}
