488	/// 设备状态帧（特征 `0xFF12`，16 字节状态 + 6 字节 Classic 地址）。
489	///
490	/// [lastCtrlOp] 与 [gnssRxCount] 是设备侧的回显字段：前者证明控制写入已被处理，
491	/// 后者证明 GNSS 下行已被接收。P0 靠这两个字段完成端到端验证。
492	class CompanionStatus {
493	  /// 直接按字段构造，一般只在测试中使用。
494	  const CompanionStatus({
495	    required this.flags,
496	    required this.batteryPct,
497	    required this.lastCtrlOp,
498	    required this.storageFreeKb,
499	    required this.uptimeSec,
500	    required this.gnssRxCount,
501	    this.classicAddrRaw = const [],
502	  });
503	
504	  /// 状态字段字节长度（不含 Classic 地址拖车）。
505	  static const length = 16;
506	
507	  /// 0x0005 起的完整线格式。
508	  static const wireLength = 22;
509	
510	  /// 电量未知时 [batteryPct] 的取值。
511	  static const batteryUnknown = 0xFF;
512	
513	  /// 状态位域，取值见 [CompanionStatusFlag]。
514	  final int flags;
515	
516	  /// 电量百分比，[batteryUnknown] 表示未知。
517	  final int batteryPct;
518	
519	  /// 设备最近处理的控制操作码回显。
520	  final int lastCtrlOp;
521	
522	  /// 传输存储剩余空间，KiB。
523	  final int storageFreeKb;
524	
525	  /// 设备运行时长，秒。App 可据此发现设备重启。
526	  final int uptimeSec;
527	
528	  /// 设备累计收到的 GNSS 下行帧数。
529	  final int gnssRxCount;
530	
531	  /// Classic BD_ADDR 原始 6 字节（LSB 在前）。空表示旧固件未带拖车。
532	  final List<int> classicAddrRaw;
533	
534	  /// 给 `BluetoothSocket` 用的 `AA:BB:CC:DD:EE:FF`。空串表示未知。
535	  String get classicAddress => CompanionFs.formatBdAddr(classicAddrRaw);
536	
537	  /// 解析 16 字节状态帧（22 字节时附带 Classic 地址）；长度不足时抛 [FormatException]。
538	  factory CompanionStatus.fromBytes(List<int> data) {
539	    if (data.length < length) {
540	      throw FormatException(
541	        'Companion 状态帧长度应为 $length，实际 ${data.length}',
542	      );
543	    }
544	
545	    final bd = ByteData.sublistView(Uint8List.fromList(data));
546	    return CompanionStatus(
547	      flags: bd.getUint16(0, Endian.little),
548	      batteryPct: bd.getUint8(2),
549	      lastCtrlOp: bd.getUint8(3),
550	      storageFreeKb: bd.getUint32(4, Endian.little),
551	      uptimeSec: bd.getUint32(8, Endian.little),
552	      gnssRxCount: bd.getUint32(12, Endian.little),
553	      classicAddrRaw: data.length >= wireLength
554	          ? List<int>.from(data.sublist(length, wireLength))
555	          : const [],
556	    );
557	  }
558	
559	  /// 是否正在录制（码表骑行会话，含暂停）。
560	  bool get isRecording => flags & CompanionStatusFlag.recording != 0;
561	
562	  /// 码表判定是否正在骑行（未暂停）。
563	  bool get isMoving => flags & CompanionStatusFlag.moving != 0;
564	
565	  /// 设备是否正在采用手机下行的定位。
566	  bool get isUsingPhoneGnss => flags & CompanionStatusFlag.gpsPhone != 0;
567	
568	  /// 是否有文件传输进行中（BLE 或 USB）。
569	  bool get isTransferBusy =>
570	      flags &
571	          (CompanionStatusFlag.fsBusy | CompanionStatusFlag.usbMtpBusy) !=
572	      0;
573	
574	  /// 电量是否已知。
575	  bool get hasBattery => batteryPct != batteryUnknown;
576	
577	  @override
578	  String toString() =>
579	      'CompanionStatus(flags=0x${flags.toRadixString(16).padLeft(4, '0')}, '
580	      'batt=$batteryPct, lastCtrlOp=0x${lastCtrlOp.toRadixString(16)}, '
581	      'freeKb=$storageFreeKb, uptime=${uptimeSec}s, gnssRx=$gnssRxCount'
582	      '${classicAddress.isEmpty ? '' : ', classic=$classicAddress'})';
583	}
584	
585	/// 0xFF1A 运行槽。与固件 `COMPANION_SLOT_*` / 2SFBL `persist.boot.running` 一致。
586	abstract class CompanionSlot {
587	  static const unknown = 0;
588	  static const fw = 1;
589	  static const main = 2;
590	  static const factory = 3;
591	}
592	
593	/// 设备信息帧（特征 `0xFF1A`）。V1 为 97 字节；V2 在末尾追加 16 字节 boot 版本。
594	class CompanionDevInfo {
595	  const CompanionDevInfo({
596	    required this.slot,
597	    required this.swVersion,
598	    required this.hwVersion,
599	    this.fwName = '',
600	    this.bootVersion = '',
601	  });
602	
603	  static const swLen = 32;
604	  static const hwLen = 16;
605	  static const nameLen = 48;
606	  static const bootLen = 16;
607	  static const lengthV1 = 1 + swLen + hwLen + nameLen;
608	  static const length = lengthV1 + bootLen;
609	
610	  final int slot;
611	  final String swVersion;
612	  final String hwVersion;
613	  final String fwName;
614	  final String bootVersion;
615	
616	  /// 界面展示用：去掉 `.bin` 后缀，协议里仍是完整文件名。
617	  static String displayFwName(String name) {
618	    const suf = '.bin';
619	    if (name.length > suf.length &&
620	        name.toLowerCase().endsWith(suf)) {
621	      return name.substring(0, name.length - suf.length);
622	    }
623	    return name;
624	  }
625	
626	  String get fwLabel => displayFwName(fwName);
627	
628	  static String _cstr(List<int> data, int off, int len) {
629	    final end = off + len;
630	    var stop = end;
631	    for (var i = off; i < end; i++) {
632	      if (data[i] == 0) {
633	        stop = i;
634	        break;
635	      }
636	    }
637	    return utf8.decode(data.sublist(off, stop), allowMalformed: true).trim();
638	  }
639	
640	  factory CompanionDevInfo.fromBytes(List<int> data) {
641	    if (data.length < lengthV1) {
642	      throw FormatException(
643	        'Companion 设备信息长度至少为 $lengthV1，实际 ${data.length}',
644	      );
645	    }
646	    return CompanionDevInfo(
647	      slot: data[0],
648	      swVersion: _cstr(data, 1, swLen),
649	      hwVersion: _cstr(data, 1 + swLen, hwLen),
650	      fwName: _cstr(data, 1 + swLen + hwLen, nameLen),
651	      bootVersion: data.length >= length
652	          ? _cstr(data, lengthV1, bootLen)
653	          : '',
654	    );
655	  }
656	
657	  String get slotName => switch (slot) {
658	        CompanionSlot.fw => 'fw',
659	        CompanionSlot.main => 'main',
660	        CompanionSlot.factory => 'factory',
661	        _ => 'unknown',
662	      };
663	
664	  @override
665	  String toString() =>
666	      'CompanionDevInfo(slot=$slotName, sw=$swVersion, hw=$hwVersion'
667	      '${fwName.isEmpty ? '' : ', file=$fwName'}'
668	      '${bootVersion.isEmpty ? '' : ', boot=$bootVersion'})';
669	}
