178	  /// 连接设备并完成服务发现与状态订阅。
179	  ///
180	  /// [autoReconnect] 为 `true` 时，意外断开后按退避自动重连，直到调用
181	  /// [disconnect]。
182	  Future<void> connect(
183	    BluetoothDevice device, {
184	    bool autoReconnect = true,
185	  }) async {
186	    await _teardown();
187	
188	    _device = device;
189	    _autoReconnect = autoReconnect;
190	    _reconnectDelay = _reconnectMinDelay;
191	    if (_autoReconnect) _armWatchdog();
192	
193	    await _connectInternal();
194	  }
