196	  /// 立刻再试一次（App 回前台、蓝牙刚打开、进后台时调用）。
197	  Future<void> kickReconnect({bool resetBackoff = false}) async {
198	    if (!_autoReconnect || _device == null) return;
199	    if (isReady || isLinking || _connectInFlight) return;
200	    if (resetBackoff) _reconnectDelay = _reconnectMinDelay;
201	    _reconnectTimer?.cancel();
202	    _reconnectTimer = null;
203	    await _connectInternal();
204	  }
205	
206	  Future<void> _connectInternal() async {
207	    final device = _device;
208	    if (device == null || _connectInFlight || isReady) return;
209	    if (isLinking) return;
210	
211	    _connectInFlight = true;
212	    _setState(CompanionConnState.connecting);
213	    await AppLog.i(_tag, '连接 ${device.remoteId}');
214	
215	    try {
216	      if (FlutterBluePlus.adapterStateNow != BluetoothAdapterState.on &&
217	          FlutterBluePlus.adapterStateNow != BluetoothAdapterState.unknown) {
218	        await AppLog.w(_tag, '蓝牙未开，稍后重连');
219	        _setState(CompanionConnState.disconnected);
220	        _scheduleReconnect();
221	        return;
222	      }
223	
224	      // 先挂监听再连接，避免漏掉紧随其后的断开事件。
225	      await _connSub?.cancel();
226	      _connSub = device.connectionState.listen(_onConnectionStateChanged);
227	
228	      // mtu:null 关掉 flutter_blue_plus 自带的 MTU 请求。Android 每条连接只允许
229	      // 一次 MTU 交换，我们要让那一次用 CompanionProto.desiredMtu。
230	      await device.connect(
231	        license: License.nonprofit,
232	        timeout: const Duration(seconds: 15),
233	        mtu: null,
234	      );
235	      await _discoverAndSubscribe(device);
236	    } catch (e, st) {
237	      await AppLog.e(_tag, '连接失败: $e', st);
238	      _setState(CompanionConnState.error);
239	      _scheduleReconnect();
240	    } finally {
241	      _connectInFlight = false;
242	    }
243	  }
244	
245	  Future<void> _discoverAndSubscribe(BluetoothDevice device) async {
246	    _setState(CompanionConnState.discovering);
247	
248	    // 协商 MTU 必须在订阅之前：16 字节的状态帧在默认 23 字节 MTU 下也放得下，
249	    // 但 P1 的文件与通知分片需要大包，且重协商会打断已有订阅。
250	    if (!kIsWeb && Platform.isAndroid) {
251	      try {
252	        _mtu = await device.requestMtu(CompanionProto.desiredMtu);
253	      } catch (e) {
254	        _mtu = device.mtuNow;
255	        await AppLog.w(_tag, 'MTU 协商失败，沿用 $_mtu: $e');
256	      }
257	      try {
258	        await device.requestConnectionPriority(
259	          connectionPriorityRequest: ConnectionPriority.high,
260	        );
261	        await Future<void>.delayed(const Duration(milliseconds: 400));
262	        await device.requestConnectionPriority(
263	          connectionPriorityRequest: ConnectionPriority.high,
264	        );
265	      } catch (e) {
266	        await AppLog.w(_tag, '连接优先级 high 失败: $e');
267	      }
268	    } else {
269	      _mtu = device.mtuNow;
270	    }
271	    await AppLog.i(_tag, 'MTU=$_mtu（有效载荷 ${_mtu - 3}）');
272	
273	    final services = await device.discoverServices();
274	    final service = services.firstWhereOrNull(
275	      (s) => s.uuid == CompanionProto.service,
276	    );
277	
278	    if (service == null) {
279	      await AppLog.e(_tag, '未发现 Companion 服务 ${CompanionProto.service}');
280	      _setState(CompanionConnState.error);
281	      await _disconnectDevice();
282	      return;
283	    }
284	
285	    _protoVerChar = _findChar(service, CompanionProto.protoVersionChar);
286	    _statusChar = _findChar(service, CompanionProto.deviceStatusChar);
287	    _controlChar = _findChar(service, CompanionProto.controlChar);
288	    _gnssChar = _findChar(service, CompanionProto.gnssFixChar);
289	    _fsCmdChar = _findChar(service, CompanionProto.fsCommandChar);
290	    _fsDataChar = _findChar(service, CompanionProto.fsDataChar);
291	    _notifChar = _findChar(service, CompanionProto.notificationChar);
292	    _navChar = _findChar(service, CompanionProto.navRouteChar);
293	    _devInfoChar = _findChar(service, CompanionProto.deviceInfoChar);
294	
295	    if (_protoVerChar == null ||
296	        _statusChar == null ||
297	        _controlChar == null ||
298	        _gnssChar == null) {
299	      await AppLog.e(
300	        _tag,
301	        'Companion 服务缺少 P0 特征: '
302	        'ver=${_protoVerChar != null} status=${_statusChar != null} '
303	        'ctrl=${_controlChar != null} gnss=${_gnssChar != null}',
304	      );
305	      _setState(CompanionConnState.error);
306	      await _disconnectDevice();
307	      return;
308	    }
309	
310	    if (!await _checkProtocolVersion()) return;
311	
312	    await _readDevInfo();
313	    await _subscribeStatus(device);
314	    await _subscribeFs(device);
315	
316	    _reconnectDelay = _reconnectMinDelay;
317	    _setState(CompanionConnState.ready);
318	    await AppLog.i(_tag, '就绪');
319	
320	    await ping();
321	    _startTimeSync();
322	  }
323	
324	  /// 读 `0xFF11` 并校验版本。返回是否可以继续。
325	  Future<bool> _checkProtocolVersion() async {
326	    final raw = await _protoVerChar!.read();
327	    if (raw.length < 2) {
328	      await AppLog.e(_tag, '协议版本响应长度异常: ${raw.length}');
329	      _setState(CompanionConnState.error);
330	      await _disconnectDevice();
331	      return false;
332	    }
333	
334	    _deviceProtoVersion = raw[0] | (raw[1] << 8);
335	    final hex = _deviceProtoVersion!.toRadixString(16).padLeft(4, '0');
336	
337	    if (_deviceProtoVersion != CompanionProto.expectedVersion) {
338	      final expected = CompanionProto.expectedVersion
339	          .toRadixString(16)
340	          .padLeft(4, '0');
341	      await AppLog.w(_tag, '协议版本不一致: 设备 0x$hex，App 期望 0x$expected');
342	
343	      if (!allowVersionMismatch) {
344	        _setState(CompanionConnState.versionMismatch);
345	        _autoReconnect = false;
346	        _watchdog?.cancel();
347	        _watchdog = null;
348	        await _disconnectDevice();
349	        return false;
350	      }
351	    } else {
352	      await AppLog.i(_tag, '协议版本 0x$hex');
353	    }
354	
355	    return true;
356	  }
