129	  Future<Uint8List> _downloadAndCache(
130	    Uri uri,
131	    OtaManifest manifest, {
132	    void Function(int done, int total)? onProgress,
133	    bool Function()? shouldStop,
134	  }) async {
135	    final bytes = await _getBytes(
136	      uri,
137	      expected: manifest.size,
138	      onProgress: onProgress,
139	      shouldStop: shouldStop,
140	    );
141	    verify(manifest, bytes);
142	    try {
143	      await _saveCache(manifest, bytes);
