151	  void verify(OtaManifest manifest, List<int> bytes) {
152	    if (bytes.length != manifest.size) {
153	      throw OtaChecksumException(
154	        '大小 ${bytes.length} 与清单 ${manifest.size} 不一致',
155	      );
156	    }
157	    final got = sha256.convert(bytes).toString();
158	    if (got != manifest.sha256) {
159	      throw OtaChecksumException('SHA256 $got ≠ ${manifest.sha256}');
160	    }
161	  }
