196	  Future<({String body, DateTime? modified})> _getString(Uri uri) async {
197	    final resp = await _open(uri);
198	    if (resp.statusCode != 200) {
199	      unawaited(resp.drain<void>());
200	      throw HttpException('HTTP ${resp.statusCode}', uri: uri);
201	    }
202	    DateTime? modified;
203	    final raw = resp.headers.value(HttpHeaders.lastModifiedHeader);
204	    if (raw != null && raw.isNotEmpty) {
205	      try {
206	        modified = HttpDate.parse(raw);
207	      } catch (_) {}
208	    }
209	    final body = await resp.transform(utf8.decoder).join();
210	    return (body: body, modified: modified);
211	  }
212	
213	  Future<Uint8List> _getBytes(
214	    Uri uri, {
215	    required int expected,
216	    void Function(int done, int total)? onProgress,
217	    bool Function()? shouldStop,
218	  }) async {
219	    await AppLog.i(_tag, 'GET $uri');
220	    final resp = await _open(uri);
221	    if (resp.statusCode != 200) {
222	      unawaited(resp.drain<void>());
223	      throw HttpException('HTTP ${resp.statusCode}', uri: uri);
224	    }
225	    final total = resp.contentLength > 0 ? resp.contentLength : expected;
226	    final out = BytesBuilder(copy: false);
227	    var done = 0;
228	    await for (final chunk in resp) {
229	      if (shouldStop?.call() == true) {
230	        throw const OtaCancelledException();
231	      }
232	      out.add(chunk);
233	      done += chunk.length;
234	      onProgress?.call(done, total);
235	    }
236	    return out.takeBytes();
237	  }
238	
239	  Future<HttpClientResponse> _open(Uri uri) async {
240	    final req = await _http.getUrl(uri);
241	    req.followRedirects = true;
242	    req.maxRedirects = 5;
243	    return req.close();
244	  }
245	}
