4	/// `firmware.json` 一份发布说明。
5	class OtaManifest {
6	  const OtaManifest({
7	    required this.version,
8	    required this.hardware,
9	    required this.url,
10	    required this.sha256,
11	    required this.size,
12	    this.note = '',
13	    this.date = '',
14	  });
15	
16	  final String version;
17	  final String hardware;
18	  final String url;
19	  final String sha256;
20	  final int size;
21	  final String note;
22	
23	  /// 展示用日期，`YYYY-MM-DD`；清单未提供时可由 HTTP Last-Modified 补上。
24	  final String date;
25	
26	  factory OtaManifest.fromJson(Map<String, dynamic> json) {
27	    final version = '${json['version'] ?? ''}'.trim();
28	    final url = '${json['url'] ?? ''}'.trim();
29	    final sha = '${json['sha256'] ?? json['sha'] ?? ''}'.trim().toLowerCase();
30	    if (version.isEmpty || url.isEmpty || sha.length != 64) {
31	      throw FormatException('firmware.json 字段不完整');
32	    }
33	    final sizeRaw = json['size'];
34	    final size = sizeRaw is int
35	        ? sizeRaw
36	        : int.tryParse('$sizeRaw') ?? 0;
37	    if (size <= 0) {
38	      throw FormatException('firmware.json size 无效');
39	    }
40	    return OtaManifest(
41	      version: version,
42	      hardware: '${json['hardware'] ?? OtaConfig.defaultHardware}'.trim(),
43	      url: url,
44	      sha256: sha,
45	      size: size,
46	      note: '${json['note'] ?? ''}'.trim(),
47	      date: parseDate(
48	        json['date'] ??
49	            json['released'] ??
50	            json['releasedAt'] ??
51	            json['time'],
52	      ),
53	    );
54	  }
55	
56	  OtaManifest copyWith({String? date}) => OtaManifest(
57	        version: version,
58	        hardware: hardware,
59	        url: url,
60	        sha256: sha256,
61	        size: size,
62	        note: note,
63	        date: date ?? this.date,
64	      );
65	
66	  static String formatDay(DateTime d) {
67	    final l = d.toLocal();
68	    final y = l.year.toString().padLeft(4, '0');
69	    final m = l.month.toString().padLeft(2, '0');
70	    final day = l.day.toString().padLeft(2, '0');
71	    return '$y-$m-$day';
72	  }
73	
74	  /// 清单里的日期字段：`YYYY-MM-DD`、ISO 时间或 unix 秒/毫秒。
75	  static String parseDate(Object? raw) {
76	    if (raw == null) return '';
77	    if (raw is int) {
78	      final ms = raw > 9999999999 ? raw : raw * 1000;
79	      return formatDay(DateTime.fromMillisecondsSinceEpoch(ms, isUtc: true));
80	    }
81	    final s = '$raw'.trim();
82	    if (s.isEmpty) return '';
83	    if (RegExp(r'^\d{4}-\d{2}-\d{2}').hasMatch(s)) {
84	      return s.substring(0, 10);
85	    }
86	    final n = int.tryParse(s);
87	    if (n != null) return parseDate(n);
88	    try {
89	      return formatDay(DateTime.parse(s));
90	    } catch (_) {
91	      return '';
92	    }
93	  }
94	
95	  /// 落到码表 `fw/` 下的文件名。必须以 `X.Y.Z` 开头，2SFBL 按文件名排版本。
96	  String get slotFileName => '$version-${OtaConfig.fileStem}.bin';
97	
98	  /// BLE 相对路径。
99	  String get slotPath => CompanionFs.otaPath(slotFileName);
100	
101	  Uri get downloadUri => OtaConfig.preferHttps(Uri.parse(url));
102	}
103	
104	/// 从文件名或版本字符串解析开头的 `X.Y.Z`。
105	class OtaVersion {
106	  const OtaVersion(this.major, this.minor, this.patch);
107	
108	  final int major;
109	  final int minor;
110	  final int patch;
111	
112	  static final _re = RegExp(r'v?(\d+)\.(\d+)\.(\d+)');
113	
114	  static OtaVersion? tryParse(String raw) {
115	    final m = _re.firstMatch(raw.trim());
116	    if (m == null) return null;
117	    return OtaVersion(
118	      int.parse(m.group(1)!),
119	      int.parse(m.group(2)!),
120	      int.parse(m.group(3)!),
121	    );
122	  }
123	
124	  static OtaVersion parseOrZero(String raw) =>
125	      tryParse(raw) ?? const OtaVersion(0, 0, 0);
126	
127	  int compareTo(OtaVersion other) {
128	    final a = major.compareTo(other.major);
129	    if (a != 0) return a;
130	    final b = minor.compareTo(other.minor);
131	    if (b != 0) return b;
132	    return patch.compareTo(other.patch);
133	  }
134	
135	  bool operator >(OtaVersion o) => compareTo(o) > 0;
136	  bool operator <(OtaVersion o) => compareTo(o) < 0;
137	  bool operator >=(OtaVersion o) => compareTo(o) >= 0;
138	
139	  @override
140	  String toString() => '$major.$minor.$patch';
141	
142	  /// 在一组 `*.bin` 名里取版本最高的；没有合法版本则空。
143	  static String? highestLabel(Iterable<String> names) {
144	    String? best;
145	    OtaVersion? bestV;
146	    for (final name in names) {
147	      if (!name.toLowerCase().endsWith('.bin')) continue;
148	      final v = tryParse(name);
149	      if (v == null) continue;
150	      if (bestV == null || v > bestV) {
151	        bestV = v;
152	        best = name;
153	      }
154	    }
155	    return best;
156	  }
157	}
