959	    var lastLogMs = 0;
960	    void report(int done) {
961	      onProgress?.call(done, total);
962	      final ms = sw.elapsedMilliseconds;
963	      if (done < total && ms - lastLogMs < 250) return;
964	      lastLogMs = ms;
965	      final kbs = (done - offset) * 1000 / (ms < 1 ? 1 : ms) / 1024;
966	      AppLog.i(
967	        _tag,
968	        '下载 ${kbs.toStringAsFixed(1)} KB/s  $done/$total '
969	        '(${sw.elapsedMilliseconds} ms)',
970	      );
971	    }
972	
973	    report(off);
974	    final rle = CompanionRle.shouldCompress(path);
975	    var wireTotal = 0;
976	    var loggedRle = false;
977	    while (left > 0) {
978	      final want = left > _fsReadBurst ? _fsReadBurst : left;
979	      final pathb = _pathBytes(path);
980	      final pkt = Uint8List(9 + pathb.length);
981	      pkt.setAll(0, _u32leBytes(off));
982	      pkt.setAll(4, _u32leBytes(want));
