987	        wireTotal += chunk.length;
988	        if (rle) {
989	          final wire = chunk.length;
990	          chunk = CompanionRle.decode(chunk);
991	          if (!loggedRle) {
992	            loggedRle = true;
993	            AppLog.i(
994	              _tag,
995	              '下载 RLE ${chunk.length}←$wire '
