1010	          left -= e.partial!.length;
1011	          report(off);
1012	        }
1013	        gaps++;
1014	        if (gaps > 3 || left <= 0) rethrow;
1015	        await AppLog.w(_tag, 'READ 重试 offset=$off ($gaps/3): $e');
1016	        await Future<void>.delayed(const Duration(milliseconds: 80));
1017	      }
1018	    }
1019	    if (rle && wireTotal > 0) {
1020	      final raw = off - offset;
1021	      AppLog.i(
1022	        _tag,
1023	        '下载 RLE 合计 $raw←$wireTotal '
1024	        '(${(raw / wireTotal).toStringAsFixed(1)}x, ${sw.elapsedMilliseconds} ms)',
1025	      );
