1156	      AppLog.i(
1157	        _tag,
1158	        '上传 ${kbs.toStringAsFixed(1)} KB/s  $done/${data.length} '
1159	        '(${sw.elapsedMilliseconds} ms)',
1160	      );
1161	    }
1162	
1163	    if (useRle) {
1164	      AppLog.i(
1165	        _tag,
1166	        '上传 RLE ${rawRemain.length}→${payload.length} '
1167	        '(${(rawRemain.length / (payload.isEmpty ? 1 : payload.length)).toStringAsFixed(1)}x)',
1168	      );
1169	    }
1170	
1171	    void throwIfPushFailed() {
1172	      final err = _fsWritePushErr;
1173	      if (err != null) {
1174	        throw err;
1175	      }
1176	    }
1177	
1178	    while (wireOff < payload.length) {
1179	      throwIfPushFailed();
1180	      final n = (payload.length - wireOff) > chunkMax
1181	          ? chunkMax
1182	          : (payload.length - wireOff);
1183	      final frame = Uint8List(CompanionFs.dataHdrLen + n);
1184	      frame[0] = CompanionFs.writeData;
1185	      frame[1] = tid;
1186	      frame[2] = 0;
1187	      frame[3] = 0;
1188	      frame[4] = seq & 0xff;
1189	      frame[5] = (seq >> 8) & 0xff;
1190	      frame[6] = n & 0xff;
1191	      frame[7] = (n >> 8) & 0xff;
1192	      frame.setAll(
1193	        CompanionFs.dataHdrLen,
1194	        payload.sublist(wireOff, wireOff + n),
1195	      );
1196	      final noRsp = dataChar.properties.writeWithoutResponse;
1197	      // 中间帧 WRITE_CMD；每 16 包带一次响应，避免码表 RX 环满丢包。
1198	      // 设备落盘时若每包都等 ATT ACK，整段上传会拖成几十秒。
1199	      final last = wireOff + n >= payload.length;
1200	      final credit = (seq % 16) == 15;
1201	      final useNr = noRsp && !last && !credit;
1202	      await dataChar.write(frame, withoutResponse: useNr);
1203	      wireOff += n;
1204	      seq++;
1205	      final done = offset +
1206	          ((wireOff * rawRemain.length) /
1207	                  (payload.isEmpty ? 1 : payload.length))
1208	              .floor();
1209	      report(done > data.length ? data.length : done);
1210	    }
1211	
1212	    throwIfPushFailed();
1213	    await _fsCommand(CompanionFs.writeClose, _u32leBytes(crcAll));
1214	  }
1215	
1216	  Future<({int offset, int crc})> _fsWriteOpen(
1217	    Uint8List pathb,
1218	    int size, {
1219	    required bool resume,
1220	    required bool rle,
1221	  }) async {
1222	    final open = Uint8List(5 + pathb.length);
1223	    open.setAll(0, _u32leBytes(size));
1224	    open[4] = (resume ? CompanionFs.writeFlagResume : 0) |
1225	        (rle ? CompanionFs.writeFlagRle : 0);
1226	    open.setAll(5, pathb);
1227	    final reply = await _fsCommand(CompanionFs.writeOpen, open);
1228	    if (reply.length < CompanionFs.writeOpenReplyLen) {
1229	      throw CompanionFsException('WRITE_OPEN 回复过短');
1230	    }
1231	    final offset = _u32At(reply, 0);
1232	    if (offset > size) {
1233	      throw CompanionFsException('续传偏移 $offset 超出文件 $size');
1234	    }
1235	    return (offset: offset, crc: _u32At(reply, 4));
1236	  }
1237	
1238	  /// 删除文件或空目录，同时清掉未完成的 `*.part`。
1239	  Future<void> fsDelete(String path) async {
1240	    await _fsCommand(CompanionFs.delete, _pathBytes(path));
1241	  }
