1248	  /// 移动 / 重命名。
1249	  Future<void> fsRename(String from, String to) async {
1250	    final oldb = _pathBytes(from);
1251	    final newb = _pathBytes(to);
1252	    if (oldb.length > 255) {
1253	      throw CompanionFsException('源路径过长');
1254	    }
1255	    final payload = Uint8List(1 + oldb.length + newb.length);
1256	    payload[0] = oldb.length;
1257	    payload.setAll(1, oldb);
1258	    payload.setAll(1 + oldb.length, newb);
1259	    await _fsCommand(CompanionFs.rename, payload);
1260	  }
