1274	  Future<void> _pumpIconNeed() async {
1275	    if (_iconNeedBusy) {
1276	      return;
1277	    }
1278	    _iconNeedBusy = true;
1279	    try {
1280	      while (_iconNeedQ.isNotEmpty) {
1281	        while (_fsWait != null) {
1282	          await Future<void>.delayed(const Duration(milliseconds: 40));
1283	        }
1284	        if (!isReady) {
1285	          _iconNeedQ.clear();
1286	          return;
