1291	        } catch (e) {
1292	          await AppLog.w(_tag, '上传码表所要图标 $name 失败: $e');
1293	        }
1294	      }
1295	    } finally {
1296	      _iconNeedBusy = false;
1297	      if (_iconNeedQ.isNotEmpty && isReady) {
1298	        unawaited(_pumpIconNeed());
