1	import 'dart:typed_data';
2	
3	import 'package:geolocator/geolocator.dart';
4	import 'package:sifli_companion/ble/companion_proto.dart';
5	
6	/// `struct companion_gnss_fix` 的编解码（特征 `0xFF14`，24 字节小端）。
7	///
8	/// 骑行中由 App 以 1–5 Hz 用「无响应写」推送给码表。
9	class CompanionGnssFix {
10	  /// 按协议字段构造。各字段均为已换算到协议单位的整数。
11	  const CompanionGnssFix({
12	    required this.latE7,
13	    required this.lonE7,
14	    required this.altMm,
15	    required this.speedCentiKmh,
16	    required this.courseDeg,
17	    required this.utcSec,
18	    required this.fixQuality,
19	    required this.satellites,
20	    required this.hdopX10,
21	  });
22	
23	  /// 帧字节长度。
24	  static const length = 24;
25	
26	  /// 纬度 × 1e7，WGS84。
27	  final int latE7;
28	
29	  /// 经度 × 1e7。
30	  final int lonE7;
31	
32	  /// 海拔，毫米。
33	  final int altMm;
34	
35	  /// 速度，0.01 km/h。
36	  final int speedCentiKmh;
37	
38	  /// 航向，0–359 度。
39	  final int courseDeg;
40	
41	  /// UTC Unix 时间戳，秒。
42	  final int utcSec;
43	
44	  /// 定位质量，取值见 [CompanionFixQuality]。
45	  final int fixQuality;
46	
47	  /// 参与定位的卫星数。
48	  final int satellites;
49	
50	  /// 水平精度因子 × 10。
51	  final int hdopX10;
52	
53	  /// 由 geolocator 的 [Position] 换算构造。
54	  ///
55	  /// geolocator 不提供卫星数与 HDOP，因此 [satellites] 记 0，并用
56	  /// [Position.accuracy]（米）近似 [hdopX10]。[fixQuality] 依据是否有海拔数据
57	  /// 区分 2D / 3D。
58	  factory CompanionGnssFix.fromPosition(Position p) {
59	    final hasAltitude = p.altitude != 0 || p.altitudeAccuracy > 0;
60	
61	    return CompanionGnssFix(
62	      latE7: _clampInt32((p.latitude * 1e7).round()),
63	      lonE7: _clampInt32((p.longitude * 1e7).round()),
64	      altMm: _clampInt32((p.altitude * 1000).round()),
65	
66	      // Position.speed 是 m/s，协议要 0.01 km/h：m/s * 3.6 * 100 = m/s * 360。
67	      speedCentiKmh: _clampUint16((p.speed * 360).round()),
68	      courseDeg: _clampUint16(p.heading.isFinite ? p.heading.round() % 360 : 0),
69	      utcSec: p.timestamp.millisecondsSinceEpoch ~/ 1000,
70	      fixQuality:
71	          hasAltitude ? CompanionFixQuality.fix3d : CompanionFixQuality.fix2d,
72	      satellites: 0,
73	      hdopX10: _clampUint8((p.accuracy * 10).round()),
74	    );
75	  }
76	
77	  /// 打包为 24 字节小端帧。
78	  Uint8List toBytes() {
79	    final bd = ByteData(length);
80	    bd.setInt32(0, latE7, Endian.little);
81	    bd.setInt32(4, lonE7, Endian.little);
82	    bd.setInt32(8, altMm, Endian.little);
83	    bd.setUint16(12, speedCentiKmh, Endian.little);
84	    bd.setUint16(14, courseDeg, Endian.little);
85	    bd.setUint32(16, utcSec, Endian.little);
86	    bd.setUint8(20, fixQuality);
87	    bd.setUint8(21, satellites);
88	    bd.setUint8(22, hdopX10);
89	    bd.setUint8(23, 0); // reserved
90	    return bd.buffer.asUint8List();
91	  }
92	
93	  /// 解析 24 字节帧。轨迹点特征 `0xFF18` 与本结构同布局，末字节含义不同。
94	  factory CompanionGnssFix.fromBytes(List<int> data) {
95	    if (data.length < length) {
96	      throw FormatException('GNSS 帧长度应为 $length，实际 ${data.length}');
97	    }
98	
99	    final bd = ByteData.sublistView(Uint8List.fromList(data));
100	    return CompanionGnssFix(
101	      latE7: bd.getInt32(0, Endian.little),
102	      lonE7: bd.getInt32(4, Endian.little),
103	      altMm: bd.getInt32(8, Endian.little),
104	      speedCentiKmh: bd.getUint16(12, Endian.little),
105	      courseDeg: bd.getUint16(14, Endian.little),
106	      utcSec: bd.getUint32(16, Endian.little),
107	      fixQuality: bd.getUint8(20),
108	      satellites: bd.getUint8(21),
109	      hdopX10: bd.getUint8(22),
110	    );
111	  }
112	
113	  /// 纬度（度）。
114	  double get latitude => latE7 / 1e7;
115	
116	  /// 经度（度）。
117	  double get longitude => lonE7 / 1e7;
118	
119	  /// 海拔（米）。
120	  double get altitudeMeters => altMm / 1000.0;
121	
122	  /// 速度（km/h）。
123	  double get speedKmh => speedCentiKmh / 100.0;
124	
125	  @override
126	  String toString() =>
127	      'CompanionGnssFix(${latitude.toStringAsFixed(6)}, '
128	      '${longitude.toStringAsFixed(6)}, alt=${altitudeMeters.toStringAsFixed(1)}m, '
129	      'speed=${speedKmh.toStringAsFixed(2)}km/h, q=$fixQuality, sats=$satellites)';
130	
131	  static int _clampInt32(int v) =>
132	      v.clamp(-2147483648, 2147483647).toInt();
133	
134	  static int _clampUint16(int v) => v.clamp(0, 0xFFFF).toInt();
135	
136	  static int _clampUint8(int v) => v.clamp(0, 0xFF).toInt();
137	}
138	
139	/// 由经纬度直接构造一帧，便于联调时手填坐标。
140	CompanionGnssFix debugGnssFix({
141	  required double latitude,
142	  required double longitude,
143	  double altitudeMeters = 0,
144	  double speedKmh = 0,
145	  double courseDeg = 0,
146	}) {
147	  return CompanionGnssFix(
148	    latE7: (latitude * 1e7).round(),
149	    lonE7: (longitude * 1e7).round(),
150	    altMm: (altitudeMeters * 1000).round(),
151	    speedCentiKmh: (speedKmh * 100).round().clamp(0, 0xFFFF),
152	    courseDeg: courseDeg.round() % 360,
153	    utcSec: DateTime.now().millisecondsSinceEpoch ~/ 1000,
154	    fixQuality: CompanionFixQuality.fix3d,
155	    satellites: 12,
156	    hdopX10: 10,
157	  );
158	}
