38	/// 骑行记录拉取、GPX 写入 import/。
39	class McuSync {
40	  /// 从 `mtp/record/` 拉新 GPX 到本机。返回新增或更新条数。
41	  static Future<int> pullRideRecords(
42	    CompanionClient client, {
43	    void Function(McuSyncProgress p)? onProgress,
44	  }) async {
45	    if (!client.isReady) {
46	      throw StateError('Companion 未就绪');
47	    }
48	    final status = client.lastStatus;
49	    if (status != null && status.isTransferBusy) {
50	      throw StateError('USB/MTP 占用中');
51	    }
52	
53	    try {
54	      await client.sendControl(CompanionCtrl.syncPrep);
55	    } catch (_) {}
56	
57	    onProgress?.call(const McuSyncProgress(phase: McuSyncPhase.listing));
58	
59	    List<CompanionFsEntry> list;
60	    try {
61	      list = await client.fsList(McuFsPaths.recordDir);
62	    } catch (_) {
63	      list = const [];
64	    }
65	
66	    final store = RideRecordStore();
67	    final pending = <CompanionFsEntry>[];
68	    for (final e in list) {
69	      if (e.isDir || !e.name.toLowerCase().endsWith('.gpx')) continue;
70	      final local = store.find(e.name);
71	      if (local != null &&
72	          local.remoteSize != null &&
73	          local.remoteSize == e.size) {
74	        continue;
75	      }
76	      pending.add(e);
77	    }
78	
79	    final totalBytes = pending.fold<int>(0, (s, e) => s + e.size);
80	    var doneBytes = 0;
81	    var added = 0;
82	    onProgress?.call(
83	      McuSyncProgress(
84	        phase: McuSyncPhase.pull,
85	        done: 0,
86	        total: totalBytes,
87	      ),
88	    );
89	
90	    for (final e in pending) {
91	      final bytes = await client.fsDownload(
92	        CompanionFs.joinRel(McuFsPaths.recordDir, e.name),
93	        length: e.size,
94	        onProgress: (d, _) {
95	          onProgress?.call(
96	            McuSyncProgress(
97	              phase: McuSyncPhase.pull,
98	              done: doneBytes + d,
99	              total: totalBytes,
100	              transferred: doneBytes + d,
101	            ),
102	          );
103	        },
104	      );
105	      await store.putFile(
106	        fileName: e.name,
107	        bytes: bytes,
108	        remoteSize: e.size,
109	      );
110	      doneBytes += e.size;
111	      added++;
112	      onProgress?.call(
113	        McuSyncProgress(
114	          phase: McuSyncPhase.pull,
115	          done: doneBytes,
116	          total: totalBytes,
117	          transferred: doneBytes,
118	        ),
119	      );
120	    }
121	    return added;
122	  }
