230	  /// 用本机坐标点记录覆盖码表 `mtp/navpts/*.tsv`。
231	  static Future<int> pushNavRoutes(
232	    CompanionClient client, {
233	    void Function(McuSyncProgress p)? onProgress,
234	    int transferred = 0,
235	  }) async {
236	    _ensureReady(client);
237	    try {
238	      await client.fsMkdir('mtp');
239	    } catch (_) {}
240	    try {
241	      await client.fsMkdir(McuFsPaths.navptsDir);
242	    } catch (_) {}
243	
244	    final store = NavRouteStore();
245	    await store.load();
246	    final jobs = <({String name, List<int> bytes})>[];
247	    final keep = <String>{};
248	    for (final rec in store.items) {
249	      if (rec.points.isEmpty) continue;
250	      var fileName = GpxUtil.safeTsvFileName(rec.name);
251	      var i = 2;
252	      while (keep.contains(fileName)) {
253	        fileName = GpxUtil.safeTsvFileName('${rec.name}_$i');
254	        i++;
255	      }
256	      keep.add(fileName);
257	      final pts = [
258	        for (var k = 0; k < rec.stops.length && k < WaypointTsv.maxPts; k++)
259	          (
260	            name: rec.stops[k].name.trim().isEmpty
261	                ? '${k + 1}'
262	                : rec.stops[k].name,
263	            point: rec.stops[k].point,
264	          ),
265	      ];
266	      jobs.add((name: fileName, bytes: utf8.encode(WaypointTsv.encode(pts))));
267	      if (jobs.length >= 32) break;
268	    }
