868	    }
869	
870	    while (off < total) {
871	      final n = (total - off) > chunkMax ? chunkMax : (total - off);
872	      var flags = extraFlags;
873	      if (off == 0) flags |= CompanionNotif.flagFirst;
874	      if (off + n >= total) flags |= CompanionNotif.flagLast;
