  /// 列出并下载码表上的崩溃文件。返回新写入条数。
  static Future<int> pull(
    CompanionClient client, {
    void Function(int done, int total)? onProgress,
  }) async {
    if (!client.isReady) {
      throw StateError('Companion 未就绪');
    }
    if (client.lastStatus?.isTransferBusy == true) {
      throw StateError('USB/MTP 占用中');
    }

    final remote = await _listRemote(client);
    final files = remote.where((e) => !e.isDir).toList();
    final store = CoredumpStore.instance;
    var added = 0;
    var i = 0;
    for (final e in files) {
      onProgress?.call(i, files.length);
      final local = await store.fileFor(e.name);
      if (await local.exists() && await local.length() == e.size) {
        i++;
        continue;
      }
      final bytes = await client.fsDownload(
        CompanionFs.joinRel(CompanionFs.coredumpDir, e.name),
        length: e.size,
      );
      await local.writeAsBytes(bytes, flush: true);
      await store.markPulled(e.name, DateTime.now());
      added++;
      i++;
      onProgress?.call(i, files.length);
