  /// 保证 `eph/` 存在。目录已有则忽略。
  Future<void> ensureDir(CompanionClient client) async {
    try {
      await client.fsMkdir(CompanionFs.ephDir);
    } on CompanionFsException catch (e) {
      if (e.status != 17) rethrow;
    }
